/* Soundtrack player for the SN76496 PSG (ports C0h): three tone voices and
 * the noise channel. Every byte goes through psg(), which keeps a shadow of
 * each channel so nothing is rewritten unless it changed, and can log the
 * byte with the clock for video captures.
 *
 * Music cues (MUSIC.H, generated by tools/alfredo2_score.py) are byte streams
 * of note, drum and wait events on a sixteenth-note grid. Instruments are
 * software envelopes stepped against the clock. Sound effects borrow voice 2
 * and/or the noise channel; the music keeps running underneath and gets the
 * channel back when the effect ends.
 *
 * Time is "episode fine time": 1/256 BIOS tick since the episode started,
 * not counting pauses. Units below: u = 1/16 tick.
 */
#define EV_WAIT 0x00   /* 00..3F: wait n+1 steps */
#define EV_ON   0x40   /* 40+v, note */
#define EV_OFF  0x48   /* 48+v */
#define EV_INST 0x50   /* 50+v, instrument */
#define EV_DRUM 0x58   /* 58, kind */
#define EV_LOOP 0x60
#define EV_END  0x61
typedef struct { unsigned char att0,decay,floor,rel,vib; } Inst;
typedef struct { const unsigned char *ev;unsigned step; } Cue;
#include "MUSIC.H"

static FILE *psg_log;
static int snd_ok,snd_mute;
static unsigned long psg_bytes;
static unsigned sh_div[3],sh_att[4],sh_noise;
static void psg_raw(unsigned v)
{
#ifndef HOST
    DosSoundPsgByte(v);
#endif
    psg_bytes++;
    if(psg_log)fprintf(psg_log,"%lu %u\n",clk_fine(),v);
}
static void psg_invalidate(void)
{
    unsigned i;
    for(i=0;i<3;i++)sh_div[i]=0xffff;
    for(i=0;i<4;i++)sh_att[i]=0xff;
    sh_noise=0xff;
}
static void ch_att(unsigned ch,unsigned att)
{
    if(!snd_ok || snd_mute)return;
    if(att>15)att=15;
    if(sh_att[ch]==att)return;
    sh_att[ch]=att;psg_raw(0x90|(ch<<5)|att);
}
static void ch_div(unsigned ch,unsigned div)
{
    if(!snd_ok || snd_mute)return;
    if(div<1)div=1;
    if(div>1023)div=1023;
    if(sh_div[ch]==div)return;
    sh_div[ch]=div;psg_raw(0x80|(ch<<5)|(div&15));psg_raw(div>>4);
}
static void ch_noise(unsigned ctl)
{
    if(!snd_ok || snd_mute)return;
    /* A noise control write resets the shift register: only on change. */
    if(sh_noise==ctl)return;
    sh_noise=ctl;psg_raw(0xe0|ctl);
}
static void snd_silence(void)
{
    unsigned i;
    if(!snd_ok)return;
    for(i=0;i<4;i++)psg_raw(0x9f|(i<<5));
    psg_invalidate();
    for(i=0;i<4;i++)sh_att[i]=15;
}
/* SN76496 divisors at 3.579545 MHz for MIDI notes 45..96 (A2..C7). */
static const unsigned midi_div[52]={
 1017,960,906,855,807,762,719,679,641,605,571,539,508,480,453,428,404,381,
 360,339,320,302,285,269,254,240,226,214,202,190,180,170,160,151,143,135,
 127,120,113,107,101,95,90,85,80,76,71,67,64,60,57,53};
static unsigned note_div(int n)
{
    if(n<45)n=45;
    if(n>96)n=96;
    return midi_div[n-45];
}

/* ---- music -------------------------------------------------------------- */
typedef struct {
    unsigned long on_at,off_at;
    unsigned char note,inst,held,sounding,off_att;
} MVoice;
static MVoice mv[3];
static int cue_no=-1;
static const unsigned char *cue_p;
static unsigned long cue_start,cue_next;
static unsigned long drum_at;
static unsigned char drum_kind,drum_live;
static int sfx_tone,sfx_nz;   /* channel 2 / noise borrowed by an effect */
static unsigned long music_events,music_late,music_late_max;
/* Noise drums (Radio Shack Rave's kit): control, start attenuation, length
   in fine units. Kick, snare, closed hat, open hat, crash, low tom, hi tom. */
static const unsigned char drum_ctl[7]={2,5,4,4,4,1,0};
static const unsigned char drum_att0[7]={0,1,5,4,2,1,1};
static const unsigned drum_len[7]={560,840,230,1400,4200,1160,930};

static unsigned env_att(const MVoice *v,unsigned long now)
{
    /* 16-bit arithmetic only: an 8088 long divide costs more than a note. */
    const Inst *in=&inst_tab[v->inst];unsigned long d;unsigned age,a;
    if(!v->sounding)return 15;
    d=(now-(v->held?v->on_at:v->off_at))>>4;
    age=d>4095UL?4095U:(unsigned)d;
    if(v->held) {
        a=in->att0+(in->decay?(age/in->decay>15?15:age/in->decay):0);
        if(a>in->floor && in->floor>=in->att0)a=in->floor;
        return a>15?15:a;
    }
    if(!in->rel)return 15;
    a=v->off_att+(age/in->rel>15?15:age/in->rel);
    return a>15?15:a;
}
static unsigned env_div(const MVoice *v,unsigned long now)
{
    const Inst *in=&inst_tab[v->inst];unsigned d=note_div(v->note),ph;
    if(in->vib) {
        /* Triangle vibrato, about 6 Hz, depth in divisor steps per 8. */
        ph=(unsigned)((now-v->on_at)>>6)&7;
        ph=ph<4?ph:7-ph;
        d+=(unsigned)(((int)ph*2-3)*(int)in->vib*(int)d/512);
    }
    return d;
}
static void voice_release(MVoice *v,unsigned long t)
{
    if(!v->held)return;
    v->off_att=(unsigned char)env_att(v,t);v->held=0;v->off_at=t;
}
static void music_event(int emit)
{
    unsigned c=*cue_p++,a,v;
    (void)emit;
    if(c<0x40){cue_next+=(unsigned long)(c+1)*cues[cue_no].step;return;}
    if(c<0x48){v=c&7;a=*cue_p++;mv[v].note=(unsigned char)a;mv[v].on_at=cue_next;
        mv[v].held=1;mv[v].sounding=1;return;}
    if(c<0x50){voice_release(&mv[c&7],cue_next);return;}
    if(c<0x58){mv[c&7].inst=*cue_p++;return;}
    if(c==EV_DRUM){drum_kind=*cue_p++;drum_at=cue_next;drum_live=1;return;}
    if(c==EV_LOOP){cue_p=cues[cue_no].ev;return;}
    cue_p--; /* EV_END: stay here */
    cue_next=0xffffffffUL;
}
static void music_stop(void)
{
    unsigned i;
    cue_no=-1;drum_live=0;
    for(i=0;i<3;i++){mv[i].held=0;mv[i].sounding=0;}
}
/* Start cue c as if it began at fine time t0, caught up silently to now. */
static void music_seek(int c,unsigned long t0,unsigned long now)
{
    music_stop();
    if(c<0)return;
    cue_no=c;cue_p=cues[c].ev;cue_start=cue_next=t0;
    while(cue_next<=now)music_event(0);
}
static void music_render(unsigned long now)
{
    unsigned i,att;unsigned long age;
    for(i=0;i<3;i++) {
        if(i==2 && sfx_tone)continue;
        att=env_att(&mv[i],now);
        if(att<15)ch_div(i,env_div(&mv[i],now));
        ch_att(i,att);
        if(att>=15 && !mv[i].held)mv[i].sounding=0;
    }
    if(sfx_nz)return;
    if(drum_live) {
        age=now-drum_at;
        if(age>=drum_len[drum_kind]){drum_live=0;ch_att(3,15);}
        else {
            ch_noise(drum_ctl[drum_kind]);
            ch_att(3,drum_att0[drum_kind]+(unsigned)age*(15-drum_att0[drum_kind])/drum_len[drum_kind]);
        }
    } else ch_att(3,15);
}
static void music_poll(unsigned long now)
{
    unsigned long late;
    if(cue_no<0)return;
    while(cue_next<=now) {
        late=now-cue_next;
        if(late>music_late_max)music_late_max=late;
        if(late>256)music_late++;
        music_event(1);music_events++;
    }
}

/* ---- sound effects ------------------------------------------------------ */
#define SFX_NONE 0
#define SFX_SCRATCH 1
#define SFX_CHUNK 2
#define SFX_SPLASH 3
#define SFX_WHOOSH 4
#define SFX_REEL 5
#define SFX_FLASH 6
#define SFX_KLAXON 7
#define SFX_SURGE 8
#define SFX_GLUG 9
#define SFX_PLOP 10
#define SFX_DOOR 11
#define SFX_BLIP 12
#define SFX_THUD 13
#define SFX_COUNT 14
/* Length in fine units, and which channels each effect borrows. */
static const unsigned sfx_len[SFX_COUNT]={0,700,520,1800,900,2200,500,4800,9000,1700,420,700,180,500};
static const unsigned char sfx_use[SFX_COUNT]={0,3,3,2,2,2,1,1,2,1,3,2,1,3};
static int sfx_id;
static unsigned long sfx_at;
static unsigned long sfx_count;
static void sfx_start(int id,unsigned long t)
{
    sfx_id=id;sfx_at=t;sfx_count++;
    sfx_tone=(sfx_use[id]&1)!=0;sfx_nz=(sfx_use[id]&2)!=0;
}
static void sfx_end(void)
{
    sfx_id=SFX_NONE;sfx_tone=sfx_nz=0;
    /* Hand the channels back to the music at its current state. */
    sh_div[2]=0xffff;sh_att[2]=0xff;sh_att[3]=0xff;sh_noise=0xff;
}
static void sfx_render(unsigned long now)
{
    unsigned long age;unsigned a,f,s;
    if(sfx_id==SFX_NONE)return;
    age=now-sfx_at;
    if(age>=sfx_len[sfx_id]){ch_att(2,15);ch_att(3,15);sfx_end();return;}
    s=(unsigned)(age>>4);          /* 1/16 ticks since start */
    a=(unsigned)age/(sfx_len[sfx_id]>>4); /* 0..15 through the effect */
    switch(sfx_id) {
    case SFX_SCRATCH: /* record scratch: two wobbling pitch sweeps over hiss */
        f=(s&7)<4?60+(s&7)*80:380-(s&7)*40;
        ch_div(2,f+(s>>2)*20);ch_att(2,2+a/3);
        ch_noise(5);ch_att(3,4+a/2);break;
    case SFX_CHUNK:   /* time clock: click, then the heavy stamp */
        ch_noise(s<4?4:2);ch_att(3,s<4?3:(s<9?0:4+s/3));
        ch_div(2,900);ch_att(2,s<4?15:4+s/4);break;
    case SFX_SPLASH:  /* white noise burst falling off, then a brighter tail */
        ch_noise(s<10?5:4);ch_att(3,a<2?1:1+a*14/16);break;
    case SFX_WHOOSH:  /* rod through the air: noise swelling and falling */
        ch_noise(4);ch_att(3,a<8?12-a:4+(a-8)*11/8);break;
    case SFX_REEL:    /* ratchet: fast clicks */
        ch_noise(4);ch_att(3,(s&1)?15:3+a/4);break;
    case SFX_FLASH:   /* camera flash: rising whine */
        ch_div(2,200-s*3>20?200-s*3:20);ch_att(2,3+a/2);break;
    case SFX_KLAXON:  /* two-tone alarm */
        ch_div(2,(s/9)&1?380:300);ch_att(2,((s%9)>7)?10:2);break;
    case SFX_SURGE:   /* rumble that builds, roars, then drains */
        ch_noise(a<5?6:(a<12?6:5));ch_att(3,a<5?9-a:(a<12?0:(a-11)*3));break;
    case SFX_GLUG:    /* three falling bubbles */
        f=s%9;ch_div(2,140+f*45+(s/9)*60);ch_att(2,f<6?2+f:15);break;
    case SFX_PLOP:    /* bobber lands */
        ch_div(2,180+s*30);ch_att(2,2+s);ch_noise(5);ch_att(3,6+s*2);break;
    case SFX_DOOR:    /* door thump */
        ch_noise(2);ch_att(3,1+a);break;
    case SFX_BLIP:
        ch_div(2,120);ch_att(2,4+a/2);break;
    case SFX_THUD:    /* fish hits the ground */
        ch_div(2,1000);ch_att(2,2+a);ch_noise(2);ch_att(3,1+a);break;
    }
}
